def _vocab(
    group: str,
    number: int,
    word: str,
    word_type: str,
    english_meaning: str,
    bangla_meaning: str,
    sentence: str,
    sentence_bangla_meaning: str,
) -> dict[str, Any]:
    group_number = group.removeprefix("Group ")
    return {
        "id": f"g{group_number}-{number:02d}",
        "word": word,
        "group": group,
        "type": word_type,
        "englishMeaning": english_meaning,
        "banglaMeaning": bangla_meaning,
        "sentence": sentence,
        "sentenceBanglaMeaning": sentence_bangla_meaning,
        "masteryLevel": 0,
    }


